void label_triangulation_faces(Triangulation& triangulation) {
    // Reset all face info flags
    for (Triangulation::All_faces_iterator current_face = triangulation.all_faces_begin(); 
         current_face != triangulation.all_faces_end(); 
         ++current_face) {
        current_face->info().processed = false;
        current_face->info().interior = false;
    }

    // Use BFS from the infinite face to label all faces using odd-even rule
    std::queue<Triangulation::Face_handle> queue;

    // Start with the infinite face (exterior)
    Triangulation::Face_handle start_face = triangulation.infinite_face();
    start_face->info().processed = true;
    start_face->info().interior = false; // Infinite face is always exterior
    queue.push(start_face);

    while (!queue.empty()) {
        Triangulation::Face_handle current_face = queue.front();
        queue.pop();

        // Process all neighbors
        for (int i = 0; i < 3; ++i) {
            Triangulation::Face_handle neighbor = current_face->neighbor(i);
            if (neighbor == Triangulation::Face_handle() || neighbor->info().processed) {
                continue;
            }

            // Mark as processed
            neighbor->info().processed = true;

            // Odd-even rule: flip the interior flag when crossing a constrained edge
            if (triangulation.is_constrained(typename Triangulation::Edge(current_face, i))) {
                neighbor->info().interior = !current_face->info().interior;
            } else {
                neighbor->info().interior = current_face->info().interior;
            }

            queue.push(neighbor);
        }
    }
}

